#include <stdint.h>


int main(void)
{
    uint32_t *pClckReg = (uint32_t*)0x4002104C;
    uint32_t *portAModReg = (uint32_t*)0x48000000;
    uint32_t *portAWriteReg = (uint32_t*)0x48000014;

    uint32_t *portCModReg = (uint32_t*)0x48000800;
    uint32_t *portCInputReg = (uint32_t*)0x48000810;

    // enable GPIoA and GPIOC clock
    *pClckReg |= (1<<0);
    *pClckReg |= (1<<2);

    //configure PA5 as output
    *portAModReg &= ~(3<<10);
    *portAModReg |= (1<<10);

    //configure PC12 as input
   *portCModReg &= ~(3<<26);

   while(1){

	if ((*portCInputReg & (1<<13)) == 0){
		*portAWriteReg |= (1<<5);
	}
	else
	{
	    *portAWriteReg &= ~(1U << 5);
	}
}

}

